110: // This function takes an exporter as template parameter and a list of files.
111: // The list of files must be set in pairs: first a TIFF file to test, then a
112: // PPM, PGM, or PBM file to compare against.
113: template <typename Exporter>
114: void TestExporter(const std::vector<std::string>& testFiles)
115: {
116:   if (testFiles.size() % 2 != 0) {
117:     throw std::runtime_error("Test files must be in pairs.");
118:   }
119:   LoadParams loadParams{ 0 };
120:   Exporter exporter;
121:   for (size_t i = 0; i < testFiles.size() / 2; ++i) {
122:     const auto tiffFilePath = getFilePath(testFiles[2*i + 0]);
123:     const auto refFilePath = getFilePath(testFiles[2*i + 1]);
124:     INFO(("Test file: " + tiffFilePath.string()));
125:     INFO(("Reference file: " + refFilePath.string()));
126:     load(tiffFilePath.string(), std::ref(exporter), loadParams);
127: 
128:     const auto& image = exporter.image();
129: 
130:     try { // Gray 8bits
131:       compareToReference<uint8_t>(image, refFilePath);
132:       return;
133:     } catch (const std::exception& ex) { /* ignore */ }
134: 
135:     try { // Gray 16bits
136:       compareToReference<uint16_t>(image, refFilePath, 1);
137:       return;
138:     } catch (const std::exception& ex) { /* ignore */ }
139: 
140:     try { // Gray 32bits
141:       compareToReference<uint32_t>(image, refFilePath);
142:       return;
143:     } catch (const std::exception& ex) { /* ignore */ }
144: 
145:     try { // RGB 8bits
146:       compareToReference<netpbm::RGB8>(image, refFilePath, 1);
147:       return;
148:     } catch (const std::exception& ex) { /* ignore */ }
149: 
150:     try { // RGB 16bits
151:       compareToReference<netpbm::RGB16>(image, refFilePath, 1);
152:       return;
153:     } catch (const std::exception& ex) { /* ignore */ }
154: 
155:     try { // RGB 32bits
156:       compareToReference<netpbm::RGB32>(image, refFilePath);
157:       return;
158:     } catch (const std::exception& ex) { /* ignore */ }
159: 
160:     try { // Bitmap 1bit
161:       compareToReference<bool>(image, refFilePath);
162:       return;
163:     } catch (const std::exception& ex) { /* ignore */ }
164: 
165:     FAIL(("Unsupported reference file format: " + refFilePath.string()));
166:   }
167: }
